import json, re, serial, statistics, subprocess, time, urllib.request
p='/dev/cu.usbserial-1130'
def collect(seconds, request_status=False):
    h=serial.Serial(p,115200,timeout=0.1,write_timeout=1)
    h.dtr=False; h.rts=False
    end=time.monotonic()+seconds
    raw=bytearray()
    while time.monotonic()<end:
        n=h.in_waiting
        if n: raw.extend(h.read(n))
        time.sleep(0.05)
    if request_status:
        h.reset_input_buffer()
        for _ in range(3):
            h.write(b'status\n'); h.flush(); time.sleep(1.5)
            n=h.in_waiting
            if n: raw.extend(h.read(n))
    h.close()
    return raw.decode(errors='replace')
